/**
* v-hasPermi directive for button-level permission control
* Usage: v-hasPermi="['system:user:add']"
*/
var hasPermi = { mounted(el, binding) {
	const { value } = binding;
	const userStore = useUserStore();
	const permissions = userStore.permissions;
	const roles = userStore.roles;
	const allPermission = "*:*:*";
	const superAdmin = "admin";
	if (value && value.length > 0) {
		if (!(!permissions || permissions.length === 0 || roles.includes(superAdmin) || permissions.some((perm) => {
			return allPermission === perm || value.includes(perm);
		}))) el.parentNode && el.parentNode.removeChild(el);
	} else throw new Error("v-hasPermi requires permission value, e.g. v-hasPermi=\"['system:user:add']\"");
} };
/**
* v-hasRole directive for role-level permission control
* Usage: v-hasRole="['admin']"
*/
var hasRole = { mounted(el, binding) {
	const { value } = binding;
	const roles = useUserStore().roles;
	const superAdmin = "admin";
	if (value && value.length > 0) {
		if (!roles.some((role) => {
			return superAdmin === role || value.includes(role);
		})) el.parentNode && el.parentNode.removeChild(el);
	} else throw new Error("v-hasRole requires role value, e.g. v-hasRole=\"['admin']\"");
} };
function setupPermissionDirective(app) {
	app.directive("hasPermi", hasPermi);
	app.directive("hasRole", hasRole);
}
